import night from "@/illustrations/generated/night.json";
import { LayeredVector } from "./LayeredVector";

// The plant at night for the homepage problem section, generated by `npm run build:illustrations`
// (illustrations/model/night.ts). Its animated parts follow the `.ops-scene` styles.
export function NightVector({ label, className }: { label: string; className?: string }) {
  return <LayeredVector scene={night} label={label} className={className} />;
}

// The model's named anchors as positions over the drawing, in percent, so labels can be pinned to
// machines at any size.
export function nightAnchors(): Record<string, { x: number; y: number }> {
  const [x0, y0, width, height] = night.viewBox;
  return Object.fromEntries(
    Object.entries(night.anchors as Record<string, number[]>).map(([name, [x, y]]) => [name, { x: Math.round(((x - x0) / width) * 1000) / 10, y: Math.round(((y - y0) / height) * 1000) / 10 }]),
  );
}
